  name: 'greeting-fanout',
  description: 'Three agents print hello, hola, bonjour in parallel',
  phases: [{ title: 'Greet' }],
}

phase('Greet')
const greetings = ['hello', 'hola', 'bonjour']
const results = await parallel(greetings.map(g => () =>
  agent(`Print exactly this single word and nothing else: ${g}`, { label: g, phase: 'Greet' })
))

return greetings.map((g, i) => ({ greeting: g, output: results[i] }))
